// Answer top status text (Window 2): The summary generated by the backend verification results determines
// the overall status title displayed above the answer body. A pure function that does not touch the DOM,
// shared between app.js rendering and unit tests—ensuring that the UI text corresponds one-to-one with the
// backend status definitions and does not drift with rendering details.
//
// Mapping between states and text (consistent with the five categories of top statuses required by the
// specification):
// failed Verification failed
// conflict Evidence conflict found
// refuted Evidence refuted
// attention Key statements pending verification
// verified N items extracted and checked, all with backing evidence (N = total, "all with backing
// evidence" applies to the N verified items) and an explicit coverage limit: only the extracted claims
// were checked, other statements in the answer are outside this verification run
// none No verifiable claims extracted in this turn
export function claimTopTitle(summary, t) {
  if (!summary || typeof summary.status !== 'string') return t('核查失败');
  if (summary.status === 'verified') {
    return t('已抽取并核查 {n} 条关键断言，均有依据；覆盖范围仅限已抽取的关键断言')
      .replace('{n}', String(summary.total ?? 0));
  }
  return t({
    failed: '核查失败', conflict: '发现证据冲突', refuted: '证据反驳',
    attention: '有关键说法待核实', none: '本轮未抽取到可核查声明',
  }[summary.status] ?? '核查失败');
}
